      box-sizing: border-box;
    }

    html,
    body {
      margin: 0;
      min-height: 100%;
    }

    body {
      font-family: Inter, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
      background:
        radial-gradient(circle at top, rgba(34, 211, 238, 0.2), transparent 30%),
        linear-gradient(180deg, #0f172a 0%, var(--bg) 55%, #020617 100%);
      color: var(--text);
      line-height: 1.5;
    }

