      color: inherit;
    }

    .skip-link {
      position: absolute;
      top: 1rem;
      left: 1rem;
      transform: translateY(-180%);
      padding: 0.75rem 1rem;
      border-radius: 999px;
      background: #f8fafc;
      color: #020617;
      font-weight: 700;
      text-decoration: none;
      transition: transform 0.2s ease;
      z-index: 10;
    }

    .skip-link:focus {
      transform: translateY(0);
    }

