      min-height: 100vh;
      display: grid;
      place-items: center;
      padding: 2rem 1rem;
    }

    .panel {
      width: min(100%, 40rem);
      padding: clamp(1.5rem, 4vw, 2.5rem);
      border: 1px solid var(--panel-border);
      border-radius: 1.5rem;
      background: var(--panel);
      box-shadow: var(--shadow);
      backdrop-filter: blur(18px);
    }

    .eyebrow {
      display: inline-flex;
      align-items: center;
      gap: 0.5rem;
      margin: 0 0 1rem;
      color: var(--accent);
      font-size: 0.9rem;
      font-weight: 700;
      letter-spacing: 0.04em;
      text-transform: uppercase;
    }

    .eyebrow::before {
      content: "";
      width: 2.25rem;
      height: 1px;
      background: currentColor;
    }

    h1 {
      margin: 0 0 0.75rem;
      font-size: clamp(2rem, 4vw, 2.8rem);
      line-height: 1.1;
    }

