    .required-note,
    .field-help,
    .field-error,
    .form-status {
      margin: 0;
      font-size: 0.95rem;
    }

    .intro,
    .required-note,
    .field-help {
      color: var(--muted);
    }

    .required-note {
      margin-top: 0.75rem;
    }

    .support-form {
      display: grid;
      gap: 1rem;
      margin-top: 1.75rem;
    }

    .form-field {
      display: grid;
      gap: 0.55rem;
    }

    .form-field label {
      font-weight: 700;
    }

    .form-field[data-invalid="true"] input {
      border-color: var(--danger-border);
      box-shadow: 0 0 0 1px rgba(251, 113, 133, 0.35);
    }

    .required-indicator {
      color: var(--danger);
      margin-left: 0.2rem;
    }

    .optional-note {
      color: var(--muted);
      font-weight: 500;
    }

    input {
      width: 100%;
      min-height: 3rem;
      padding: 0.9rem 1rem;
      border: 1px solid var(--field-border);
      border-radius: 0.9rem;
      background: var(--field-bg);
      color: var(--text);
      font: inherit;
      transition: border-color 0.2s ease, box-shadow 0.2s ease, transform 0.2s ease;
    }

    input::placeholder {
      color: #64748b;
    }

    input:hover {
      border-color: #475569;
    }

    input:focus-visible,
    button:focus-visible {
      outline: 3px solid var(--accent);
      outline-offset: 2px;
    }

    input:focus {
      border-color: var(--accent-strong);
      box-shadow: 0 0 0 1px rgba(34, 211, 238, 0.25);
    }

    .field-error {
      color: var(--danger);
    }

    .actions {
      display: grid;
      gap: 0.85rem;
      margin-top: 0.5rem;
    }

    button {
      min-height: 3.25rem;
      border: 0;
      border-radius: 999px;
      padding: 0.95rem 1.4rem;
      background: linear-gradient(135deg, #67e8f9 0%, #22d3ee 100%);
      color: #082f49;
      font: inherit;
      font-weight: 800;
      cursor: pointer;
      transition: transform 0.2s ease, box-shadow 0.2s ease, filter 0.2s ease;
      box-shadow: 0 14px 34px rgba(34, 211, 238, 0.2);
    }

    button:hover {
      filter: brightness(1.05);
      transform: translateY(-1px);
    }

    .form-status {
      min-height: 1.5rem;
      color: #bfdbfe;
    }

    .visually-hidden {
      position: absolute;
      width: 1px;
      height: 1px;
      padding: 0;
      margin: -1px;
      overflow: hidden;
      clip: rect(0 0 0 0);
      white-space: nowrap;
      border: 0;
    }

    @media (max-width: 32rem) {
      .panel {
        padding: 1.25rem;
        border-radius: 1.1rem;
      }

      button {
        width: 100%;
      }
    }

    @media (forced-colors: active) {
      .skip-link,
      .panel,
      input,
      button {
        forced-color-adjust: auto;
