<body>
  <a class="skip-link" href="#main-content">Skip to main content</a>
  <div id="app"></div>

  <script>
    const fieldConfigs = [
      {
        id: "fullName",
        label: "Full name",
        type: "text",
        name: "fullName",
        autocomplete: "name",
        required: true,
        placeholder: "Taylor Morgan"
      },
      {
        id: "email",
        label: "Email address",
        type: "email",
        name: "email",
        autocomplete: "email",
        inputMode: "email",
        required: true,
        placeholder: "taylor@example.com"
      },
      {
        id: "phone",
        label: "Phone number",
        type: "tel",
        name: "phone",
        autocomplete: "tel",
        inputMode: "tel",
        required: false,
        placeholder: "(555) 123-4567",
        helperText: "Optional. Use digits with spaces, dashes, or parentheses, for example (555) 123-4567."
      }
    ];

    const state = {
      values: {
        fullName: "",
        email: "",
        phone: ""
      },
      touched: {},
      submitted: false
    };

    const refs = {};

    function createElement(tag, properties = {}, children = []) {
      const element = document.createElement(tag);

      Object.entries(properties).forEach(([key, value]) => {
        if (value === null || value === undefined || value === false) {
          return;
        }

        if (key === "className") {
          element.className = value;
          return;
        }

        if (key === "text") {
          element.textContent = value;
          return;
        }

        if (key === "html") {
          element.innerHTML = value;
          return;
        }

        element.setAttribute(key, value === true ? "" : String(value));
      });

      [].concat(children).filter(Boolean).forEach((child) => {
        element.appendChild(typeof child === "string" ? document.createTextNode(child) : child);
      });

      return element;
    }

    function getFieldError(config, value) {
      const trimmedValue = value.trim();

      if (config.required && !trimmedValue) {
        return "Error: " + config.label + " is required.";
      }

      if (config.id === "email" && trimmedValue) {
        const emailInput = document.createElement("input");
        emailInput.type = "email";
        emailInput.value = trimmedValue;

        if (!emailInput.checkValidity()) {
          return "Error: Enter an email address in the format name@example.com.";
        }
      }

      if (config.id === "phone" && trimmedValue) {
        const phonePattern = /^\+?[0-9().\-\s]{7,20}$/;

        if (!phonePattern.test(trimmedValue)) {
          return "Error: Enter a phone number using digits with spaces, dashes, or parentheses.";
        }
      }

      return "";
