      } else {
        fieldRef.input.removeAttribute("aria-describedby");
      }
    }

    function updateAllFields() {
      fieldConfigs.forEach(updateFieldState);
    }

    function FormField(config) {
      const wrapper = createElement("div", {
        className: "form-field",
        "data-invalid": "false"
      });

      const label = createElement("label", { for: config.id });
      label.appendChild(document.createTextNode(config.label));

      if (config.required) {
        label.appendChild(createElement("span", {
          className: "required-indicator",
          "aria-hidden": "true",
          text: "*"
        }));
        label.appendChild(createElement("span", {
          className: "visually-hidden",
          text: " required"
        }));
      } else {
        label.appendChild(createElement("span", {
          className: "optional-note",
          text: " (optional)"
        }));
      }

      const input = createElement("input", {
        id: config.id,
        name: config.name,
        type: config.type,
        autocomplete: config.autocomplete,
        inputmode: config.inputMode,
        placeholder: config.placeholder,
        required: config.required
      });

      input.value = state.values[config.id];

      input.addEventListener("input", (event) => {
        state.values[config.id] = event.target.value;
        if (state.submitted || state.touched[config.id]) {
          updateFieldState(config);
        }
      });

      input.addEventListener("blur", () => {
        state.touched[config.id] = true;
        updateFieldState(config);
      });

      const helpText = config.helperText
        ? createElement("p", {
            id: config.id + "-help",
            className: "field-help",
            text: config.helperText
          })
        : null;

      const error = createElement("p", {
        id: config.id + "-error",
        className: "field-error",
        hidden: true
      });

      wrapper.append(label, input);

      if (helpText) {
        wrapper.appendChild(helpText);
      }

      wrapper.appendChild(error);

      refs[config.id] = { wrapper, input, helpText, error };

      return wrapper;
    }

    function SupportForm() {
      const form = createElement("form", {
        className: "support-form",
        novalidate: true
      });

      const status = createElement("p", {
        className: "form-status",
        "aria-live": "polite"
      });

      fieldConfigs.forEach((config) => {
        form.appendChild(FormField(config));
      });

      const actions = createElement("div", { className: "actions" }, [
        createElement("button", { type: "submit", text: "Send support request" }),
        status
      ]);

      form.appendChild(actions);

      form.addEventListener("submit", (event) => {
        event.preventDefault();
        state.submitted = true;
        status.textContent = "";
        updateAllFields();

        const invalidField = fieldConfigs.find((config) => getFieldError(config, state.values[config.id]));

        if (invalidField) {
          refs[invalidField.id].input.focus();
          status.textContent = "Please correct the errors in the form and try again.";
          return;
        }

        form.reset();
        state.values = {
          fullName: "",
          email: "",
          phone: ""
