        state.touched = {};
        state.submitted = false;
        updateAllFields();
        status.textContent = "Your support request is ready to be sent.";
      });

      return form;
    }

    function App() {
      const main = createElement("main", { id: "main-content" });
      const panel = createElement("section", {
        className: "panel",
        "aria-labelledby": "page-title"
      });

      panel.append(
        createElement("p", { className: "eyebrow", text: "Support" }),
        createElement("h1", { id: "page-title", text: "Get in touch with our support team" }),
        createElement("p", {
          className: "intro",
          text: "Share your contact details and we will follow up as quickly as possible."
        }),
        createElement("p", {
          className: "required-note",
          html: '<span aria-hidden="true">*</span> Required fields'
        }),
        SupportForm()
      );

      main.appendChild(panel);

      return main;
    }

    document.getElementById("app").appendChild(App());
    updateAllFields();
  </script>
