         wrapper.appendChild(helpText);
       }

       wrapper.appendChild(error);

       refs[config.id] = { wrapper, input, helpText, error };

       return wrapper;
     }

     function SupportForm() {
       const form = createElement("form", {
         className: "support-form",
         novalidate: true
       });

       const status = createElement("p", {
         className: "form-status",
         "aria-live": "polite"
       });

       fieldConfigs.forEach((config) => {
         form.appendChild(FormField(config));
       });

       const actions = createElement("div", { className: "actions" }, [
         createElement("button", { type: "submit", text: "Send support request" }),
         status
       ]);

       form.appendChild(actions);

       form.addEventListener("submit", (event) => {
         event.preventDefault();
         state.submitted = true;
         status.textContent = "";
         updateAllFields();

         const invalidField = fieldConfigs.find((config) => getFieldError(config, state.values[config.id]));

         if (invalidField) {
           refs[invalidField.id].input.focus();
           status.textContent = "Please correct the errors in the form and try again.";
           return;
         }

         form.reset();
         state.values = {
           fullName: "",
           email: "",
           phone: ""
         };
         state.touched = {};
         state.submitted = false;
         updateAllFields();
         status.textContent = "Your support request is ready to be sent.";
       });

       return form;
     }

     function App() {
       const main = createElement("main", { id: "main-content" });
       const panel = createElement("section", {
         className: "panel",
         "aria-labelledby": "page-title"
       });

       panel.append(
         createElement("p", { className: "eyebrow", text: "Support" }),
         createElement("h1", { id: "page-title", text: "Get in touch with our support team" }),
         createElement("p", {
           className: "intro",
           text: "Share your contact details and we will follow up as quickly as possible."
         }),
         createElement("p", {
           className: "required-note",
           html: '<span aria-hidden="true">*</span> Required fields'
         }),
         SupportForm()
       );

       main.appendChild(panel);

       return main;
     }

     document.getElementById("app").appendChild(App());
     updateAllFields();
   </script>
 </body>
 </html>

